//! Generated by tools/build-kagami-art.py. Presentation only.
pub const RENEW: usize = 3;
pub fn frame(pose: &str, elapsed: usize) -> usize {
    let ticks: &[usize] = match pose {
        "idle" => &[18, 18, 18, 18],
        "run" => &[8, 8, 8, 8, 8, 8],
        "attack" => &[4, 5, 3, 10],
        "skill1" => &[4, 5, 5, 4],
        "skill2" => &[4, 5, 5, 4],
        "ult" => &[4, 5, 5, 4],
        "hit" => &[8],
        "dead" => &[8, 8, 8, 8, 8, 8],
        _ => &[18,18,18,18],
    };
    let total:usize=ticks.iter().sum();
    let mut time=if matches!(pose,"idle"|"run") {elapsed%total} else {elapsed.min(total-1)};
    for (i,t) in ticks.iter().enumerate(){if time<*t{return i;}time-=t;}
    ticks.len()-1
}
